CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', language text NOT NULL DEFAULT 'en', age_group text NOT NULL DEFAULT 'adult', country text, accessibility text NOT NULL DEFAULT '', requested_role text NOT NULL DEFAULT 'learner');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TYPE public.app_role AS ENUM ('learner','teacher','mentor','admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'learner', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE FUNCTION public.create_learner_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,language,age_group,country,accessibility,requested_role) VALUES (NEW.id, coalesce(NEW.raw_user_meta_data->>'full_name',''), coalesce(NEW.raw_user_meta_data->>'language','en'), coalesce(NEW.raw_user_meta_data->>'age_group','adult'), NEW.raw_user_meta_data->>'country', coalesce(NEW.raw_user_meta_data->>'accessibility',''), coalesce(NEW.raw_user_meta_data->>'requested_role','learner')); INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'learner'); RETURN NEW; END $$;
CREATE TRIGGER on_edupeace_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_learner_profile();
CREATE TABLE public.enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, course_slug text NOT NULL CHECK (course_slug IN ('digital-literacy','peace-dialogue','english-literacy','financial-literacy','environment','entrepreneurship')), completed_lessons integer[] NOT NULL DEFAULT '{}', enrolled_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,course_slug), CHECK(completed_lessons <@ ARRAY[0,1,2]));
GRANT SELECT, INSERT, UPDATE ON public.enrollments TO authenticated; GRANT ALL ON public.enrollments TO service_role;
ALTER TABLE public.enrollments ENABLE ROW LEVEL SECURITY;
CREATE POLICY enrollment_read ON public.enrollments FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY enrollment_insert ON public.enrollments FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND completed_lessons = '{}');
CREATE POLICY enrollment_update ON public.enrollments FOR UPDATE TO authenticated USING(user_id = auth.uid()) WITH CHECK(user_id = auth.uid());
CREATE TABLE public.peace_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, message text NOT NULL CHECK(char_length(message) BETWEEN 10 AND 600), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.peace_messages TO anon; GRANT SELECT, INSERT, UPDATE ON public.peace_messages TO authenticated; GRANT ALL ON public.peace_messages TO service_role;
ALTER TABLE public.peace_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY wall_read ON public.peace_messages FOR SELECT TO anon, authenticated USING(status = 'approved' OR user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY wall_insert ON public.peace_messages FOR INSERT TO authenticated WITH CHECK(user_id = auth.uid() AND status = 'pending' AND EXISTS(SELECT 1 FROM public.profiles WHERE id = auth.uid() AND age_group = 'adult'));
CREATE POLICY wall_moderate ON public.peace_messages FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX enrollments_user_idx ON public.enrollments(user_id); CREATE INDEX peace_messages_user_idx ON public.peace_messages(user_id); CREATE INDEX user_roles_user_idx ON public.user_roles(user_id);